import React, { useState } from 'react';

function Login() {
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // TODO: เชื่อม backend ที่นี่เมื่อกดปุ่ม ส่ง OTP
  // เชื่อม API: POST /api/auth/request-otp { email }
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    try {
      // --- ที่นี่จะเรียก API ขอ OTP ---
      // let res = await fetch('/api/auth/request-otp', {...});
      // แล้ว redirect ไปหน้า verify-otp พร้อมพารามิเตอร์ email
      // ตัวอย่าง: navigate(`/verify-otp?email=${email}`);
    } catch (err) {
      setError('ส่ง OTP ไม่สำเร็จ ‐ กรุณาลองใหม่');
    }
    setIsLoading(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-neutral-50 animate-fade-in">
      <div className="w-full max-w-md mx-auto shadow-xl rounded-3xl overflow-hidden bg-white">
        <div className="bg-gradient-primary text-white p-8 text-center rounded-b-3xl relative">
          <span className="material-icons-round text-5xl animate-bounce">lock</span>
          <h1 className="mt-3 text-3xl font-bold tracking-tight">เข้าสู่ระบบ ClaimMate</h1>
          <p className="text-white80 mt-2">สำหรับทุกบทบาทในระบบ</p>
        </div>
        <form className="p-8 flex flex-col gap-5" onSubmit={handleSubmit}>
          <div>
            <label htmlFor="email" className="block text-sm font-medium text-neutral-dark mb-2">
              อีเมล
            </label>
            <input
              type="email"
              id="email"
              autoComplete="email"
              required
              className="w-full px-4 py-3 rounded-xl border border-neutral-200 focus:border-primary-500 bg-neutral-50 text-neutral-dark placeholder-neutral-400 font-medium transition duration-200"
              placeholder="example@email.com"
              value={email}
              onChange={e => setEmail(e.target.value)}
              disabled={isLoading}
            />
          </div>
          {!!error && (
            <div className="text-error text-sm px-2 py-1 rounded bg-error bg-opacity-10 border border-error">
              {error}
            </div>
          )}
          <button 
            type="submit"
            disabled={isLoading}
            className={`w-full py-3 rounded-xl font-bold text-lg shadow-button text-white bg-gradient-primary transition-all duration-300 ${
              isLoading ? 'opacity-50' : 'hover:scale-105 hover:shadow-glow-primary'
            } animate-pulse`}
          >
            {isLoading ? 'กำลังส่ง...' : 'เข้าสู่ระบบ / ขอ OTP'}
          </button>
        </form>
        <div className="py-4 px-6 text-center text-neutral-500 text-xs">
          <span>
            © 2025 ClaimMate ระบบแจ้งเคลมประกันของทุกบทบาท
          </span>
        </div>
      </div>
    </div>
  );
}

/*
  TODO:
  - เชื่อม backend โดยส่ง req POST /api/auth/request-otp พร้อม email
  - ถ้า success, ไปหน้า verify-otp?
  - ถ้า error, แจ้งบนหน้าฟอร์ม
  - ใช้ className ตรงกับธีม gradient สี ปุ่ม และเงา ของกลุ่ม customer
  - Responsive ด้วย max-w-md, padding มากบนมือถือ, container flex
  - มีแอนิเมชันเล็กน้อย เช่น animate-bounce, animate-pulse, animate-fade-in สำหรับว้าว
*/

export default Login;
